import{c as e,Q as a,j as s,m as i}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"PRD-023 · /explore zoom-in detail layer — make planet focus a destination, not just a closeup","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-023.md","filePath":"prd/PRD-023.md"}'),o={name:"prd/PRD-023.md"};function r(n,t,l,d,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="prd-023-·-explore-zoom-in-detail-layer-—-make-planet-focus-a-destination-not-just-a-closeup" tabindex="-1">PRD-023 · /explore zoom-in detail layer — make planet focus a destination, not just a closeup <a class="header-anchor" href="#prd-023-·-explore-zoom-in-detail-layer-—-make-planet-focus-a-destination-not-just-a-closeup" aria-label="Permalink to &quot;PRD-023 · /explore zoom-in detail layer — make planet focus a destination, not just a closeup&quot;">​</a></h1><blockquote><p>Status · Draft Date · 2026-06-03 Owner · Marko Closes into · GH issue <a href="https://github.com/chipi/orrery/issues/301" target="_blank" rel="noreferrer">#301</a>, per-slice implementation issues Builds on · #287 (planet-relative camera + 4K LOD + natural satellites + atmospheric halos)</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> Spans three subsystems: visual rendering (new 3D primitives + texture swaps + shader-ish overlays), data (fleet entries for active orbiters that aren&#39;t yet in <code>/fleet/orbiter/</code>, plus new &quot;active-around-planet&quot; relations), and UX (decision matrix for what&#39;s &quot;always-on detail&quot; vs what&#39;s gated by the Science Lens vs what lives in the HUD/panel). One owner, one categorisation decision, one source of truth before per-feature slices start.</p></blockquote><h2 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h2><p>After #287 the user can fly into a planet, get the 4K texture + atmospheric halo + moons. The view is beautiful but <strong>passive</strong> — it shows a textured sphere with moons, nothing more. There&#39;s no reason to <em>stay</em> zoomed in.</p><p>This PRD locks the spec for turning the planet-focus pose into a <strong>destination</strong> with story-rich layers a user would actually explore:</p><ul><li><strong>Always-on detail</strong> — physical features that are simply <em>there</em> (mission spacecraft orbiting, ring shadows, axial tilt, city lights). No toggle.</li><li><strong>Science Lens additions</strong> — conceptual physics overlays gated on the existing lens toggle (Hill sphere, Lagrange points, magnetic field, sub-solar point).</li><li><strong>HUD / info-panel additions</strong> — text + UI affordances (light-time, scale comparison, planet stats, prograde indicator).</li></ul><p>The full set spans ~10 distinct features. This PRD groups them, picks the marquee 4 for the first slice, and surfaces the fleet-data implications.</p><h2 id="the-meta-decision" tabindex="-1">The META decision <a class="header-anchor" href="#the-meta-decision" aria-label="Permalink to &quot;The META decision&quot;">​</a></h2><p><strong>Where does each feature belong — zoom-in detail, Science Lens, or HUD?</strong></p><p>The principle:</p><table tabindex="0"><thead><tr><th>Category</th><th>What belongs here</th><th>Why</th></tr></thead><tbody><tr><td><strong>Always-on detail</strong></td><td>Things that <em>exist</em> in physical reality at the depicted moment</td><td>A user shouldn&#39;t have to toggle a layer to see that Jupiter has rings, that Mars has spacecraft around it, or that Earth has city lights. These are facts.</td></tr><tr><td><strong>Science Lens</strong></td><td>Conceptual physics that&#39;s <em>invisible to the eye</em></td><td>Magnetic fields, Lagrange points, Hill spheres — you can&#39;t <em>see</em> these by looking at the planet. Lens makes the physics-of-the-system visible by user choice.</td></tr><tr><td><strong>HUD / panel</strong></td><td>Reference info, scale anchors, navigation cues</td><td>Light-time, gravity, &quot;Earth diameter at this scale&quot; — text + tiny UI affordances. Always-on text-y stuff, not 3D geometry.</td></tr></tbody></table><p>Each candidate feature classified below.</p><h2 id="categorised-feature-catalogue" tabindex="-1">Categorised feature catalogue <a class="header-anchor" href="#categorised-feature-catalogue" aria-label="Permalink to &quot;Categorised feature catalogue&quot;">​</a></h2><h3 id="always-on-zoom-in-detail-slice-a" tabindex="-1">Always-on zoom-in detail (Slice A) <a class="header-anchor" href="#always-on-zoom-in-detail-slice-a" aria-label="Permalink to &quot;Always-on zoom-in detail (Slice A)&quot;">​</a></h3><p>These render on every planet at every zoom level below <code>PLANET_LOD_IN_RATIO</code>. No user toggle.</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Per-body specifics</th><th>Data needs</th></tr></thead><tbody><tr><td>1</td><td><strong>Active orbiters as 3D glyphs</strong></td><td>Mars: MRO, MAVEN, Mars Express, ExoMars TGO, Hope, Mangalyaan, Tianwen-1. Jupiter: Juno. Saturn: (none active; historical Cassini ghost path). Venus: Akatsuki. Earth: ISS + Tiangong (already on /earth — link or render here too).</td><td>Per-orbiter altitude_km + inclination_deg in <code>/fleet/orbiter/&lt;id&gt;.json</code>. Today partial; need to backfill for missions that lack it.</td></tr><tr><td>2</td><td><strong>Spin axis with obliquity tilt</strong></td><td>Line through planet centre at real axial tilt. Earth 23°, Uranus 98°, Venus 177°.</td><td><code>axialTilt</code> field in <code>planets.json</code> (already present).</td></tr><tr><td>3</td><td><strong>Ring shadow on Saturn</strong></td><td>Dark band across Saturn&#39;s cloud tops where rings occlude sunlight. Anti-solar projection of ring annulus onto sphere.</td><td>None — geometric only.</td></tr><tr><td>4</td><td><strong>Galilean shadows on Jupiter</strong></td><td>Real-time transit shadow dots for Io/Europa/Ganymede/Callisto on Jupiter&#39;s day side when geometrically possible.</td><td>None — projection of moon position onto planet surface.</td></tr><tr><td>5</td><td><strong>Earth&#39;s night-side city lights</strong></td><td>Swap to a city-lights texture on the night hemisphere. Standard astro-visualisation trick.</td><td>New <code>4k_earth_lights.jpg</code> texture (NASA Black Marble, public domain).</td></tr><tr><td>6</td><td><strong>Hero spacecraft trajectory</strong></td><td>Per planet, one notable mission&#39;s path drawn as a fading arc. Voyager 2&#39;s outbound from Uranus / Neptune. Juno&#39;s polar plunge at Jupiter. Cassini grand-finale at Saturn.</td><td>Per-mission trajectory polylines — could derive from existing /fly cislunar data or hand-author short arcs per body.</td></tr></tbody></table><p><strong>Marquee 4 for the first slice</strong> (highest visual-return per LOC):</p><ul><li><strong>A1 — Active orbiters at Mars</strong> (5+ active missions, immediate &quot;you&#39;re visiting&quot; feel)</li><li><strong>A2 — Spin axis on Uranus</strong> (Uranus on its side is the single most &quot;wait what&quot; fact in the solar system)</li><li><strong>A3 — Saturn&#39;s ring shadow</strong> (the iconic photo, every Saturn render needs it)</li><li><strong>A4 — Earth&#39;s city lights</strong> (most viscerally &quot;alive&quot; detail, swaps a texture)</li></ul><p>Remaining items (Galilean shadows, hero trajectories, other-planet orbiters) land in Slice C.</p><h3 id="science-lens-additions-slice-b" tabindex="-1">Science Lens additions (Slice B) <a class="header-anchor" href="#science-lens-additions-slice-b" aria-label="Permalink to &quot;Science Lens additions (Slice B)&quot;">​</a></h3><p>Toggled by the existing Science Lens button. Conceptual physics overlays that don&#39;t appear in nature.</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Description</th><th>Where the lens unlocks it</th></tr></thead><tbody><tr><td>7</td><td><strong>Magnetic field / radiation belts</strong></td><td>Stylised teardrop shell around the planet showing magnetosphere shape. Jupiter&#39;s tail extends to Saturn&#39;s orbit. Earth Van Allen.</td><td>New lens layer <code>magnetosphere</code></td></tr><tr><td>8</td><td><strong>Hill sphere boundary</strong></td><td>Translucent wireframe sphere at the gravity-dominance radius. The &quot;you&#39;re in this planet&#39;s authority&quot; volume.</td><td>New lens layer <code>hill-sphere</code></td></tr><tr><td>9</td><td><strong>Lagrange points L1–L5</strong></td><td>Five labeled markers around the orbit. L2 = JWST sits here. L4/L5 = Trojan asteroids.</td><td>New lens layer <code>lagrange-points</code></td></tr><tr><td>10</td><td><strong>Sub-solar point + terminator emphasis</strong></td><td>Pulsing dot at planet&#39;s noon longitude + sharper day/night line. Anchors &quot;the Sun is THAT way&quot;.</td><td>Currently the gravity arrows do this implicitly — promote to its own layer?</td></tr></tbody></table><p><strong>Marquee 2 for Slice B</strong>:</p><ul><li><strong>B1 — Hill sphere</strong> (universal, simple geometry, sci-fi-rich)</li><li><strong>B2 — Lagrange points</strong> (educational, scientifically real, photogenic markers)</li></ul><p>Remaining items (magnetic field, sub-solar point) land in Slice D.</p><h3 id="hud-panel-additions-slice-e-—-polish" tabindex="-1">HUD / panel additions (Slice E — polish) <a class="header-anchor" href="#hud-panel-additions-slice-e-—-polish" aria-label="Permalink to &quot;HUD / panel additions (Slice E — polish)&quot;">​</a></h3><p>Always-on text + UI. No 3D geometry.</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td>11</td><td><strong>Light-time + distance HUD</strong></td><td>&quot;5.2 AU · 43 light-minutes from Sun&quot; overlay near the panel header.</td></tr><tr><td>12</td><td><strong>Earth silhouette comparison</strong></td><td>Faint Earth-radius ghost sphere in viewport corner. Instant &quot;Jupiter is 11× Earth&quot; read.</td></tr><tr><td>13</td><td><strong>Compass rose / prograde indicator</strong></td><td>Tiny widget on the planet&#39;s orbit showing prograde direction + spin direction.</td></tr><tr><td>14</td><td><strong>Planet stats overlay</strong></td><td>Floating semitransparent labels — GRAVITY, ATMOSPHERIC PRESSURE, ROTATION PERIOD — sci-fi &quot;tactical scan&quot; feel.</td></tr></tbody></table><h2 id="slice-order" tabindex="-1">Slice order <a class="header-anchor" href="#slice-order" aria-label="Permalink to &quot;Slice order&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Slice A — Marquee 4 always-on detail   (orbiters at Mars + Uranus tilt + Saturn ring shadow + Earth city lights)</span></span>
<span class="line"><span>Slice B — Marquee 2 lens overlays      (Hill sphere + Lagrange points)</span></span>
<span class="line"><span>Slice C — Remaining always-on detail   (Galilean shadows + hero trajectories + other-planet orbiters)</span></span>
<span class="line"><span>Slice D — Remaining lens overlays      (magnetic field + sub-solar point)</span></span>
<span class="line"><span>Slice E — HUD polish                   (light-time + Earth-comparison + compass + stats overlay)</span></span></code></pre></div><p>Each slice ships as its own commit + e2e check. /explore baseline e2e regression suite stays green throughout.</p><h2 id="data-implications-—-fleet-additions" tabindex="-1">Data implications — fleet additions <a class="header-anchor" href="#data-implications-—-fleet-additions" aria-label="Permalink to &quot;Data implications — fleet additions&quot;">​</a></h2><p>Active orbiters that need fleet entries (or backfill of altitude_km + inclination_deg) for Slice A&#39;s rendering:</p><table tabindex="0"><thead><tr><th>Planet</th><th>Mission</th><th>In <code>/fleet/orbiter/</code>?</th><th>Notes</th></tr></thead><tbody><tr><td>Mars</td><td>MRO</td><td>yes (<code>mro.json</code>)</td><td>Verify altitude_km/inclination_deg present</td></tr><tr><td>Mars</td><td>MAVEN</td><td>check</td><td>If missing, add</td></tr><tr><td>Mars</td><td>Mars Express</td><td>yes (<code>mars-express.json</code>)</td><td>Verify orbit params</td></tr><tr><td>Mars</td><td>ExoMars TGO</td><td>check</td><td>If missing, add</td></tr><tr><td>Mars</td><td>Hope (EMM)</td><td>check</td><td>If missing, add (UAE — flags &quot;global space programs&quot; memory)</td></tr><tr><td>Mars</td><td>Mangalyaan</td><td>yes (<code>mangalyaan.json</code>)</td><td>Verify orbit params</td></tr><tr><td>Mars</td><td>Tianwen-1</td><td>check</td><td>China; verify present</td></tr><tr><td>Jupiter</td><td>Juno</td><td>yes (<code>juno.json</code>)</td><td>Verify orbit params</td></tr><tr><td>Venus</td><td>Akatsuki</td><td>check</td><td>If missing, add (JAXA)</td></tr><tr><td>Earth</td><td>ISS, Tiangong</td><td>yes (separate route)</td><td>Cross-link only</td></tr></tbody></table><p>The &quot;global space programs&quot; memory applies: ensure CNSA / ISRO / JAXA / Roscosmos / UAESA orbiters are present alongside NASA&#39;s, not silently dropped.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li><strong>Real-time spacecraft positions</strong> — pinned orbits are fine for v1; live ephemerides are a separate initiative.</li><li><strong>Surface-route changes</strong> — /earth /moon /mars stay independent. /explore zoom-in is the only route touched.</li><li><strong>Heliocentric view</strong> — wide zoom unchanged. Only the planet-focus pose (below <code>PLANET_LOD_IN_RATIO</code>) gets the new layers.</li><li><strong>i18n strings for the new HUD labels</strong> — Slice E ships en-US; locale propagation is a separate slice once strings stabilise.</li></ul><h2 id="risks-open-questions" tabindex="-1">Risks + open questions <a class="header-anchor" href="#risks-open-questions" aria-label="Permalink to &quot;Risks + open questions&quot;">​</a></h2><ol><li><strong>Crowding.</strong> Each layer adds visual weight. The previous Jupiter-focus screenshot was already busy with moons + halo + arrows. Need a clear visibility hierarchy. → Mitigation: per-slice screenshots in PR descriptions; user-pref toggles in Slice E if needed.</li><li><strong>Fleet-data debt.</strong> Backfilling orbital params for the missing orbiters is real work — Akatsuki, Hope, MAVEN, ExoMars TGO need accurate altitude + inclination. → Slice A spec includes the data audit as Step 0.</li><li><strong>Decision: do magnetic field + sub-solar lens layers belong in Slice D, or do they actually belong in Slice A?</strong> Reasonable counter-argument: magnetic field is a <em>physical</em> thing that exists (Earth&#39;s aurora is the visible proof). → Keep in lens for v1; revisit after Slice A ships and we see how busy the focus view feels.</li></ol><h2 id="done-definition" tabindex="-1">Done definition <a class="header-anchor" href="#done-definition" aria-label="Permalink to &quot;Done definition&quot;">​</a></h2><ul><li>Slices A + B shipped (marquee 4 always-on + marquee 2 lens)</li><li>/explore e2e regression suite green</li><li>/fleet has entries for every orbiter rendered as a 3D glyph in Slice A</li><li>Each planet&#39;s zoom-in shows ≥ 1 new layer (orbiter, ring shadow, axial tilt, city lights, hero arc) beyond #287&#39;s baseline</li><li>Slices C-E filed as discrete follow-up issues with concrete scope (not &quot;phase 2&quot; hand-waves)</li></ul>`,42)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
